// Token Launch Radar — offline dashboard (token-radar-01).
// Loads ./data.json (generated by main.ts), renders the board + detail views.
// No network calls: the only URLs are outbound <a href> links from the data.
"use strict";

const $ = (id) => document.getElementById(id);
let ROWS = [];
let SUMMARY = null;

const fmtMoney = (n) => "$" + Math.round(n).toLocaleString("en-US");
const fmtCompact = (n) => {
  if (n >= 1e9) return "$" + (n / 1e9).toFixed(2) + "B";
  if (n >= 1e6) return "$" + (n / 1e6).toFixed(1) + "M";
  if (n >= 1e3) return "$" + (n / 1e3).toFixed(1) + "K";
  return fmtMoney(n);
};
const fmtPct = (x) => {
  // tvlChange7d is already in percent units in the DefiLlama data
  // (e.g. -0.59 means -0.59%, per the confidence reasons in board.json),
  // NOT a fraction — do not multiply by 100.
  if (x === null || x === undefined) return "—";
  const p = Number(x).toFixed(2);
  return (x > 0 ? "+" : "") + p + "%";
};
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const confPct = (c) => Math.round(c * 100) + "%";

function fillSelect(sel, values) {
  for (const v of values) {
    const o = document.createElement("option");
    o.value = v; o.textContent = v;
    sel.appendChild(o);
  }
}

function currentFilters() {
  return {
    q: $("f-search").value.trim().toLowerCase(),
    category: $("f-category").value,
    chain: $("f-chain").value,
    minTvl: Number($("f-min-tvl-num").value || 0) * 1e6,
    minConf: $("f-confidence").value === "" ? 0 : Number($("f-confidence").value),
    sort: $("f-sort").value,
  };
}

function applyFilters() {
  const f = currentFilters();
  let rows = ROWS.filter((r) => {
    if (f.q && !(r.name.toLowerCase().includes(f.q) || r.slug.toLowerCase().includes(f.q))) return false;
    if (f.category && r.category !== f.category) return false;
    if (f.chain && !r.chains.includes(f.chain)) return false;
    if (r.tvlUsd < f.minTvl) return false;
    if (r.confidence < f.minConf) return false;
    return true;
  });
  const by = {
    "implied-desc": (a, b) => b.impliedValueUsd - a.impliedValueUsd,
    "implied-asc": (a, b) => a.impliedValueUsd - b.impliedValueUsd,
    "tvl-desc": (a, b) => b.tvlUsd - a.tvlUsd,
    "tvl-asc": (a, b) => a.tvlUsd - b.tvlUsd,
    "name-asc": (a, b) => a.name.localeCompare(b.name),
    "name-desc": (a, b) => b.name.localeCompare(a.name),
  };
  rows = rows.slice().sort(by[f.sort] || by["implied-desc"]);
  renderTable(rows);
  $("count").textContent = rows.length + " of " + ROWS.length + " shown";
}

function renderTable(rows) {
  const tb = $("tbody");
  tb.innerHTML = rows.map((r) => {
    const chg = r.tvlChange7d;
    const cls = chg === null || chg === undefined ? "" : (chg >= 0 ? "pos" : "neg");
    const chains = r.chains.slice(0, 3).map((c) => `<span class="pill">${esc(c)}</span>`).join("") + (r.chains.length > 3 ? ` <span class="pill">+${r.chains.length - 3}</span>` : "");
    return `<tr data-slug="${esc(r.slug)}" class="${r.rank <= 10 ? "top10" : ""}">
      <td class="num">${r.rank}</td>
      <td class="name">${esc(r.name)} <span class="slug">${esc(r.slug)}</span></td>
      <td>${esc(r.category)}</td>
      <td>${chains}</td>
      <td class="num" title="${fmtMoney(r.tvlUsd)}">${fmtCompact(r.tvlUsd)}</td>
      <td class="num ${cls}">${fmtPct(chg)}</td>
      <td class="num" title="${fmtMoney(r.impliedValueUsd)}">${fmtCompact(r.impliedValueUsd)}</td>
      <td class="num">${confPct(r.confidence)}</td>
    </tr>`;
  }).join("");
}

function renderDetail(slug) {
  const r = ROWS.find((x) => x.slug === slug);
  const board = $("board-view"), detail = $("detail-view");
  if (!r) {
    board.hidden = false; detail.hidden = true;
    $("error").hidden = false;
    $("error").textContent = "No protocol with slug “" + slug + "” on this board.";
    return;
  }
  $("error").hidden = true;
  board.hidden = true; detail.hidden = false;
  const chg = r.tvlChange7d;
  const cls = chg === null || chg === undefined ? "" : (chg >= 0 ? "pos" : "neg");
  const comps = r.comparables.map((c) => `<tr><td>${esc(c.name)}</td><td class="num" title="${fmtMoney(c.mcapUsd)}">${fmtCompact(c.mcapUsd)}</td><td class="num" title="${fmtMoney(c.tvlUsd)}">${fmtCompact(c.tvlUsd)}</td><td class="num">${Number(c.ratio).toFixed(3)}</td></tr>`).join("");
  const fp = r.farmPlan || {};
  const steps = (fp.steps || []).map((s) => `<li>${esc(s)}</li>`).join("");
  const risks = (fp.risks || []).map((s) => `<li>${esc(s)}</li>`).join("");
  const links = [];
  if (r.website) links.push(`<a href="${esc(r.website)}" target="_blank" rel="noopener">Website</a>`);
  if (r.defillamaUrl) links.push(`<a href="${esc(r.defillamaUrl)}" target="_blank" rel="noopener">DefiLlama</a>`);
  if (r.twitter) links.push(`<a href="https://x.com/${esc(r.twitter)}" target="_blank" rel="noopener">X / Twitter: @${esc(r.twitter)}</a>`);
  $("detail").innerHTML = `<article class="detail-card">
    <h2>#${r.rank} &mdash; ${esc(r.name)}</h2>
    <p class="meta">${esc(r.slug)} &middot; ${esc(r.category)} &middot; ${r.chains.map(esc).join(", ")} &middot; token status: ${esc(r.tokenStatus)} &middot; source: ${esc(r.source)} &middot; fetched ${esc(r.fetchedAt)}</p>
    <div class="dgrid">
      <div class="stat"><span class="k">TVL</span><span class="v">${fmtMoney(r.tvlUsd)}</span></div>
      <div class="stat"><span class="k">TVL change (7d)</span><span class="v ${cls}">${fmtPct(chg)}</span></div>
      <div class="stat"><span class="k">Implied value</span><span class="v">${fmtMoney(r.impliedValueUsd)}</span></div>
      <div class="stat"><span class="k">Confidence</span><span class="v">${confPct(r.confidence)}</span></div>
    </div>
    <h3>Implied value &mdash; method</h3>
    <p>${esc(r.impliedValueMethod)}</p>
    <p>Category median mcap/TVL ratio: <strong>${Number(r.categoryMedianRatio).toFixed(4)}</strong>. Implied value is a proxy, not FDV.</p>
    <h3>Confidence</h3>
    <p>${confPct(r.confidence)} &mdash; ${esc(r.confidenceReason)}</p>
    <h3>Comparables (tokenized, same category where available)</h3>
    <div class="table-wrap"><table><thead><tr><th>Name</th><th class="num">Market cap</th><th class="num">TVL</th><th class="num">mcap / TVL</th></tr></thead><tbody>${comps}</tbody></table></div>
    <h3>Farm plan</h3>
    <ol>${steps}</ol>
    <p><strong>Points / rewards:</strong> ${esc(fp.pointsOrRewards || "No confirmed airdrop or points programme in the DefiLlama data for this protocol.")}</p>
    <p><strong>Estimated cost:</strong> ${fp.estimatedCostUsd !== undefined ? fmtMoney(fp.estimatedCostUsd) : "—"} &middot; <strong>Estimated time:</strong> ${fp.estimatedTimeMin !== undefined ? fp.estimatedTimeMin + " min" : "—"}</p>
    <h3>Risks</h3>
    <ul>${risks}</ul>
    <h3>Links</h3>
    <p class="links">${links.length ? links.join("") : "No links in the data for this protocol."}</p>
  </article>`;
  window.scrollTo(0, 0);
}

function showBoard() {
  $("detail-view").hidden = true;
  $("board-view").hidden = false;
  $("error").hidden = true;
}

function route() {
  const m = location.hash.match(/^#\/protocol\/([\w\-.]+)/);
  if (m) renderDetail(decodeURIComponent(m[1]));
  else showBoard();
}

function applyQueryParams() {
  const p = new URLSearchParams(location.search);
  if (p.get("q")) $("f-search").value = p.get("q");
  if (p.get("category")) $("f-category").value = p.get("category");
  if (p.get("chain")) $("f-chain").value = p.get("chain");
  if (p.get("minTvl")) { $("f-min-tvl").value = p.get("minTvl"); $("f-min-tvl-num").value = p.get("minTvl"); }
  if (p.get("minConf")) $("f-confidence").value = p.get("minConf");
  if (p.get("sort")) $("f-sort").value = p.get("sort");
}

async function init() {
  try {
    const res = await fetch("data.json");
    if (!res.ok) throw new Error("data.json returned HTTP " + res.status);
    const data = await res.json();
    ROWS = data.rows || [];
    SUMMARY = data.summary || null;
  } catch (e) {
    $("error").hidden = false;
    $("error").textContent = "Could not load data.json (" + e.message + "). Open this page from the dashboard folder (file:// with --allow-file-access-from-files, or any local static server).";
    $("count").textContent = "Data failed to load.";
    return;
  }
  if (SUMMARY) {
    $("stat-rows").textContent = SUMMARY.rows;
    $("stat-tvl").textContent = fmtCompact(SUMMARY.totalTvlUsd);
    $("stat-tvl").title = fmtMoney(SUMMARY.totalTvlUsd);
    $("stat-implied").textContent = fmtCompact(SUMMARY.totalImpliedValueUsd);
    $("stat-implied").title = fmtMoney(SUMMARY.totalImpliedValueUsd);
    $("stat-median").textContent = fmtCompact(SUMMARY.medianImpliedValueUsd);
    $("stat-cats").textContent = SUMMARY.categories.length;
  }
  fillSelect($("f-category"), [...new Set(ROWS.map((r) => r.category))].sort());
  fillSelect($("f-chain"), [...new Set(ROWS.flatMap((r) => r.chains))].sort());
  applyQueryParams();
  applyFilters();
  route();
}

["f-search", "f-category", "f-chain", "f-confidence", "f-sort"].forEach((id) => $(id).addEventListener("input", applyFilters));
$("f-min-tvl").addEventListener("input", () => { $("f-min-tvl-num").value = $("f-min-tvl").value; applyFilters(); });
$("f-min-tvl-num").addEventListener("input", () => { $("f-min-tvl").value = $("f-min-tvl-num").value; applyFilters(); });
$("f-clear").addEventListener("click", () => {
  $("f-search").value = ""; $("f-category").value = ""; $("f-chain").value = "";
  $("f-min-tvl").value = 0; $("f-min-tvl-num").value = 0; $("f-confidence").value = ""; $("f-sort").value = "implied-desc";
  applyFilters();
});
$("tbody").addEventListener("click", (e) => {
  const tr = e.target.closest("tr[data-slug]");
  if (tr) location.hash = "#/protocol/" + tr.dataset.slug;
});
$("back").addEventListener("click", () => { location.hash = "#/"; });
document.querySelectorAll("th[data-sort]").forEach((th) => th.addEventListener("click", () => {
  const key = th.dataset.sort;
  const map = { rank: "implied-desc", name: "name-asc", category: "name-asc", tvlUsd: "tvl-desc", tvlChange7d: "tvl-desc", impliedValueUsd: "implied-desc", confidence: "implied-desc" };
  // Toggle direction for numeric sorts already active on that column.
  const cur = $("f-sort").value;
  if (key === "tvlUsd") $("f-sort").value = cur === "tvl-desc" ? "tvl-asc" : "tvl-desc";
  else if (key === "impliedValueUsd") $("f-sort").value = cur === "implied-desc" ? "implied-asc" : "implied-desc";
  else if (key === "name") $("f-sort").value = cur === "name-asc" ? "name-desc" : "name-asc";
  else $("f-sort").value = map[key] || "implied-desc";
  applyFilters();
}));
window.addEventListener("hashchange", route);
document.addEventListener("DOMContentLoaded", init);
